}

const STOP_PATH =
  'M180,20H76A56.06,56.06,0,0,0,20,76V180a56.06,56.06,0,0,0,56,56H180a56.06,56.06,0,0,0,56-56V76A56.06,56.06,0,0,0,180,20Z'

function StopIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 256 256"
