    { children, disabled, destructive, textValue, onClick, onMouseEnter, className, ...props },
    ref,
  ) => {
    const { nextIndex } = useDropdownMenuCtx('DropdownMenuItem')
    const { setActiveIndex, focusedIndex, setFocusedIndex, setOpen, registerItem } =
      useDropdownMenuContentCtx('DropdownMenuItem')

    const itemRef = useRef<HTMLDivElement | null>(null)

    const indexRef = useRef<number | null>(null)
    if (indexRef.current === null) indexRef.current = nextIndex()
    // eslint-disable-next-line react-hooks/refs
    const index = indexRef.current
    useEffect(() => {
      const el = itemRef.current
      if (index < 0 || !el) return
      registerItem(index, el)
      return () => registerItem(index, null)
    }, [index, registerItem])

    const setItemRef = useCallback(
      (node: HTMLDivElement | null) => {
        itemRef.current = node
        if (typeof ref === 'function') ref(node)
        else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node
      },
      [ref],
    )

    return (
      <div
        ref={setItemRef}
        role="menuitem"
        tabIndex={focusedIndex === index ? 0 : -1}
        data-disabled={disabled ? '' : undefined}
        data-proximity-index={index}
        aria-disabled={disabled || undefined}
        aria-label={textValue}
        className={cn(
          'relative flex min-h-11 w-full cursor-default select-none scroll-m-1 items-center justify-between gap-3 rounded-md px-3 py-2.5 text-left text-sm outline-none transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
          'data-disabled:pointer-events-none data-disabled:opacity-50',
          destructive
            ? 'text-(--color-error) focus-visible:text-(--color-error)'
            : 'text-(--color-fg)',
          className,
        )}
        onPointerDown={(e) => {
          e.preventDefault()
        }}
        onFocus={() => {
          setFocusedIndex(index)
          setActiveIndex(index)
        }}
        onClick={() => {
          if (disabled) return
          playClickSound()
          onClick?.()
          setOpen(false)
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            if (!disabled) {
              playClickSound()
              onClick?.()
              setOpen(false)
            }
          }
        }}
        onMouseEnter={(e) => {
          onMouseEnter?.(e)
          if (!disabled) playHoverSound()
        }}
        {...props}
      >
        <span className="relative z-10 flex min-w-0 flex-1 items-center gap-2 truncate">
          {children}
        </span>
      </div>
    )
